import numpy as np
from scipy import ndimage
F=np.load('source_pixels.npz')['rgb']
for t in range(96):
 a=F[t].astype(int); R,G,B=a.transpose(2,0,1)
 masks={
 'red':(R-G>15)&(R-B>10)&(R>60),
 'strict':(R-G>25)&(R-B>20)&(R>80),
 'satred':(R>1.25*G)&(R>1.15*B)&(R>70),
 }
 if t%4==0:
  print('T',t,end=' ')
  for n,m in masks.items():
   lab,N=ndimage.label(m)
   comps=[]
   for i in range(1,N+1):
    yy,xx=np.where(lab==i); s=len(xx)
    if s>=3: comps.append((s,round(xx.mean(),1),round(yy.mean(),1),(xx.min(),yy.min(),xx.max(),yy.max())))
   print(n,sorted(comps,reverse=True)[:4],end=' | ')
  print()
